const request = $json.body ?? $json;
const docId = String(request.docId ?? '').trim();
if (!docId) throw new Error('docId is required.');
return [{ json: {
  docId,
  docUrl: `https://docs.google.com/document/d/${docId}/edit`,
  meetingType: request.meetingType ?? 'unspecified',
  meetingDate: request.meetingDate ?? null,
  source: request.source ?? { kind: 'manual-doc-intake' }
} }];

const request = $('Normalize Doc Request').item.json;
const body = $json.body ?? $json;
const text = [];
for (const content of body.body?.content ?? []) {
  for (const element of content.paragraph?.elements ?? []) {
    if (element.textRun?.content) text.push(element.textRun.content);
  }
}
return [{ json: { ...request, meetingText: text.join('') } }];

