const request = $('Normalize Complete Notes').item.json;
const raw = $json.output ?? $json.text ?? $json.response ?? '{}';
let result;
try {
  result = JSON.parse(String(raw).replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim());
} catch (error) {
  result = { items: [], completeness: { extracted: 0, classified: 0 }, parseError: String(error) };
}
const items = Array.isArray(result.items) ? result.items : [];
const widgets = [{ textParagraph: { text: `Meeting: ${request.meetingType} | Doc: ${request.docUrl}` } }];
for (const item of items) {
  widgets.push({ textParagraph: { text: `<b>${item.classification}</b><br>${item.rawText}<br><i>${item.reason}</i>` } });
}
return [{ json: { chatResponse: { cardsV2: [{ cardId: `meeting-${Date.now()}`, card: { header: { title: 'Meeting notes intake review', subtitle: `${items.length} items` }, sections: [{ widgets }] } }] } } }];
